$string['categoryhero_contrastfloor'] = 'These colours read {$a->ratio}:1; the minimum is {$a->floor}:1. Use a suggestion of the contrast panel.';
$string['categoryhero_cover'] = 'Card cover';
$string['categoryhero_cover_help'] = 'The still of this category\'s card in the course index, cropped to a wide and short frame. While there is none, the card falls back to the background image above it; while there is neither, it shows the colour band alone. Around 640 x 300 pixels. One file: adding another replaces it, and deleting it puts the card back on the image above.';
$string['categoryhero_covervideo'] = 'Cover video';
$string['categoryhero_covervideo_help'] = 'A short film played on the card, without sound, while a pointer rests on it. The cover image is what loads first and what a reader who never hovers sees. MP4 or WebM, a few seconds on a loop, 720p is enough, up to the size limit set for the site. Subtitles are not offered on this field, so nothing in the film may depend on speech. One file: adding another replaces it, and deleting it leaves the card with its still alone.';
$string['categoryhero_defaultsort'] = 'Default organisation';
$string['categoryhero_defaultsort_help'] = 'How this category\'s page is organised when the address names no organisation: by area (a poster per subcategory), A-Z, or the most recent first. A reader can still pick another one on the toolbar, and a link that names one keeps it. "Theme default" is by area; a category with no subcategories then simply lists its courses.';
$string['categoryhero_defaultsort_theme'] = 'Theme default (by area)';
$string['categoryhero_descriptionheader'] = 'Description';
$string['categoryhero_fold'] = 'Collapse';
$string['categoryhero_image'] = 'Background image';
$string['categoryhero_image_help'] = 'A real photograph of an operation or a training session. The colour overlay is applied over it, it is shown with the "Band with a background image" layout, and the site-wide image stands in while the category has none of its own. One file: adding another replaces it, and deleting it brings the site-wide image back.';
$string['categoryhero_inheritedabove'] = 'Without colours of its own, this category uses the colours of a category above it.';
$string['categoryhero_inheritedfrom'] = 'Without colours of its own, this category uses the colours of {$a}.';
$string['categoryhero_inheritedtheme'] = 'Without colours of its own, this category uses the theme\'s colours: no category above it has any.';
$string['categoryhero_inkcolour'] = 'Text colour';
$string['categoryhero_inkcolour_help'] = 'The colour of the name, the tagline and the description on the band, written as #rrggbb. White reads on almost every deep colour; a pale band needs a dark text colour instead. The focus ring of the controls on the band follows this colour, so a ring is never invisible.';
$string['categoryhero_invalidchoice'] = 'This is not one of the choices offered.';
$string['categoryhero_invalidcolour'] = 'Enter a colour as #rrggbb.';
$string['categoryhero_invalidvideo'] = 'This file is not an MP4 or a WebM video. Choose a file whose contents really are one: the name of a file is not what is checked.';
$string['categoryhero_layout'] = 'Hero layout';
$string['categoryhero_layout_compact'] = 'Compact, title only';
$string['categoryhero_layout_image'] = 'Band with a background image';
$string['categoryhero_layout_solid'] = 'Band in a solid colour';
$string['categoryhero_nav'] = 'Category appearance';
$string['categoryhero_overlay'] = 'Overlay intensity';
$string['categoryhero_overlay_60'] = 'Light - 60%';
$string['categoryhero_overlay_78'] = 'Medium - 78%';
$string['categoryhero_overlay_90'] = 'Strong - 90%';
$string['categoryhero_overlay_help'] = 'How much of the colour covers the photograph. The contrast panel measures the pair on the solid band; over a photograph the colour is translucent, so the text reads lower - measured against a white photograph, the institutional navy reads 4.9:1 at 60%, 8.9:1 at 78% and 12.3:1 at 90%, and a lighter band needs more coverage. Prefer 78% or more when the picture is bright. "Transparent" applies no colour at all and shows the photograph alone: nothing then stands between the text and the picture, so use it only with a photograph you have checked the text against.';
$string['categoryhero_overlay_transparent'] = 'Transparent - 0%';
$string['categoryhero_owncolours'] = 'Own colours';
$string['categoryhero_owncolours_help'] = 'Ticked, the two colours below are this category\'s own, and they reach its subcategories that have none of their own. Unticked, the category takes the colours of the nearest category above it that has its own, or the theme\'s colours when none has; the two fields then show those colours and cannot be edited. The background and the text colour always come together from the same category, because they were checked for contrast as a pair. The layout, the overlay, the texts and the images are never inherited.';
$string['categoryhero_owncolours_label'] = 'Use colours of its own for this category';
$string['categoryhero_pairpreview'] = 'Preview of the pair on the solid band';
$string['categoryhero_pencil'] = 'Customise category';
$string['categoryhero_public'] = 'Public page';
$string['categoryhero_publicsummary'] = 'Public description';
$string['categoryhero_publicsummary_help'] = 'One or two sentences about the category for people outside the platform: this is the text a messaging app, a social network or a search result shows under the link when the category\'s public page is shared. Plain text, no formatting, at most {$a} characters, because that is all a preview shows. Leave it empty and the shared link shows only the category name. The text below is what a visitor reads on the page itself.';
$string['categoryhero_publicsummary_toolong'] = 'The public description is limited to {$a} characters, which is what a share preview shows.';
$string['categoryhero_publictext'] = 'Public page text';
$string['categoryhero_publictext_help'] = 'What a visitor who is not logged in reads on the category\'s public page, once the category is published. The category\'s own description above is written for the people who are logged in. The image and multimedia buttons here LINK to media that is already published somewhere else - a video address, a picture address - and store nothing on this site: this text has no file area of its own, so an image pasted or dropped into it is refused when the page is saved.';
$string['categoryhero_publictext_nofiles'] = 'This text can only link to media published somewhere else, and an image pasted or dropped into it is stored nowhere. Remove it and use its address instead.';
$string['categoryhero_saved'] = 'Category appearance saved.';
$string['categoryhero_stat_enrolled'] = 'you are enrolled in';
$string['categoryhero_stat_hidden'] = 'hidden from students';
$string['categoryhero_stat_total'] = 'courses and events';
$string['categoryhero_tagline'] = 'Tagline';
$string['categoryhero_tagline_help'] = 'One sentence under the category name. The category description keeps being shown below it.';
$string['categoryhero_unfold'] = 'Expand';
$string['categoryherofallback'] = 'Site-wide hero image';
$string['categoryherofallback_desc'] = 'The photograph behind the hero of a category whose layout asks for an image while the category has none of its own.';
$string['categorypageenabled'] = 'Show the category showcase';
$string['categorypageenabled_desc'] = 'The category page: every course of the category and its subcategories a person may discover, as cards or as a dense list, with the enrolment state of each one, search, filters and a favourite star. Switched off, the category page is exactly what Boost Union renders, whatever the other settings of this tab say. Boost Union\'s own course listing presentation setting does not apply while the showcase is shown.';
$string['categorypagesize'] = 'Courses per page';
$string['categorypagesize_desc'] = 'How many courses the page lists before offering the next page.';
$string['categorypublicclient'] = 'Live listing for visitors';
$string['categorypublicclient_desc'] = 'The web service that lets a public category page search, filter and turn pages without reloading: theme_dimensions_get_public_category_rows, through lib/ajax/service-nologin.php, which needs no login. It answers only what the public page itself shows the same visitor, refuses every logged-in session, and refuses a category that is not public exactly as it refuses one that does not exist. Off, which is the default, it refuses every request and the public pages reload for every search, filter and page; they are served either way. Before switching it on, limit the rate of requests to lib/ajax/service-nologin.php in the web server.';
$string['categorypublicenabled'] = 'Serve public categories to visitors';
$string['categorypublicenabled_desc'] = 'The public page of a category local_unlistedcourses holds in the public state, for visitors who are not logged in: the category\'s hero and its public courses, with Open Graph tags for social previews, at theme/dimensions/category.php?id=N (or its route). Switched off, every anonymous request is refused with the login page and nobody is forwarded, whatever state a category is in; the state stays stored.';
$string['categoryrootpublic'] = 'Serve the root of the course index to visitors';
$string['categoryrootpublic_desc'] = 'The root of the course index - the directory of top-level categories - for visitors who are not logged in, at theme/dimensions/category/0 (or its script). Only the top-level categories local_unlistedcourses holds in the public state get a card there, which is fewer than a logged-in reader sees: a merely listed category has no page a visitor may open. The page names no course and carries no search, no filter and no favourite. Off, which is the default, every anonymous request for the root is refused with the login page, exactly as a category that is not public is; the categories keep their own states either way.';
$string['categorystatesort'] = 'Group courses by enrolment state';
$string['categorystatesort_desc'] = 'The courses a person is enrolled in or has applied to come first, then the ones they could join, then the rest, each group in the category\'s own order; the status chips print how many courses each state holds. Switched off, the listing keeps the category\'s order alone, the status chips are not offered, and the page is cut in the database - the choice for a category tree of more than ten thousand courses.';
$string['categorytreedepth'] = 'Navigation depth';
$string['categorytreedepth_all'] = 'Every level';
$string['categorytreedepth_desc'] = 'How many levels below the listed category the navigation offers: the tree beside the listing and the accordion of the "By category" organisation. It bounds what is OFFERED and never what is LISTED - the page always lists the whole subtree of the category, however deep, and a category further down is reached through the "Access category" button of its nearest offered ancestor.';
$string['categoryunavailable'] = 'This category is not available.';
$string['choosereadme'] = 'Dimensions is a child theme of Boost Union. It looks and behaves like Boost Union and adds its own login page, category showcase, landing pages and focus mode on top of it.';
