$string['landingfield_liveclasseswhen'] = 'When the live classes happen';
$string['landingfield_liveclasseswhen_desc'] = 'A short line shown with the live classes on the enrolment landing page, such as "Wednesdays, every other week, 7 pm to 8.30 pm". Never the broadcast link: that is delivered inside the course.';
$string['landingfield_meetings'] = 'In-person meetings';
