$string['loginpanelheading'] = 'Institutional panel';
$string['loginpanelheading_desc'] = 'The copy of the panel beside the login form. Each field left empty shows its language string (login_panel_kicker, login_panel_title, login_panel_text, login_panel_foot), which follows the user\'s language and can be edited through Language customisation; a value typed here is shown to everyone exactly as typed. Below the lg breakpoint the panel gives way to a band above the form, which shows the kicker.';
$string['loginpanelkicker'] = 'Kicker';
