$string['navbarautohide_activity'] = 'Activity pages';
$string['navbarautohide_course'] = 'The course page';
$string['navbarautohide_desc'] = 'On the pages ticked here the navbar slides up as the reader scrolls down and comes back on the first scroll up; its 3px band stays at the top of the screen, showing the reading progress. It never hides while the keyboard focus is in it, one of its menus is open or a side drawer is open over the page, and the side drawers move up with it. Never in the Moodle app, in focus mode, while Boost Union\'s menu bar is shown, or on a Behat test site. None by default.';
$string['navbarcompact'] = 'Compact navbar on tablets';
$string['navbarcompact_desc'] = 'Between tablet and desktop widths, when the site\'s navigation would send more than two of its items into the "More" menu, the navbar takes the phone\'s layout instead: the menu button, the logo and the icons on the right, with the navigation in the side menu. Decided in the browser from what the navigation itself measured, so it follows the window, the language and the number of items; until it has measured, the navigation is held back so it never shows items about to go. Never in the Moodle app or in focus mode. Switched off, the navbar keeps every width\'s own layout.';
$string['navbarcontextbar'] = 'Context bar while reading';
$string['navbarcontextbar_desc'] = 'On activity pages and the course page, once the reader scrolls past the page title, the navbar\'s content gives way, at the same height, to the activity\'s (or the course\'s) name, the course and "X of Y completed", the activity\'s completion status (read only: the button stays in core\'s footer) and a button that opens the course index. Scrolling up brings the navbar back. Not in focus mode, on the front page, in the Moodle app, or for visitors while "Log in and sign-up for visitors" is on. Switched off, the navbar stays as it is.';
$string['navbarcontextcolor'] = 'Context bar colour';
$string['navbarcontextcolor_desc'] = 'The colour the context bar takes when it comes in, so the change from the navbar is seen at once; the text on it is white or dark, whichever reads at the contrast WCAG AA asks for. A hexadecimal colour such as #1d4f91. Empty, the colour is derived from the brand colour: a lighter or darker step of it that keeps that contrast.';
$string['navbardrawer'] = 'Side menu for logged-in accounts';
$string['navbardrawer_desc'] = 'On a phone, the side menu of a logged-in account opens on who is logged in, a "Continue where you left off" card with the last activity opened and the course\'s progress (asked for when the menu is first opened, never with the page), the site\'s navigation and each of Boost Union\'s smart menus in labelled sections whose sub-menus slide in, and at its foot the colour mode (while core\'s colour modes are enabled) and the language (while the site offers more than one). Visitors and the guest account keep Boost Union\'s menu, with the "New here?" card. Never shown in the Moodle app. Switched off, the menu is Boost Union\'s.';
$string['navbarguestactions'] = 'Log in and sign-up for visitors';
$string['navbarguestactions_desc'] = 'Replaces the navbar\'s "Log in" link, and the "You are currently using guest access" sentence the guest account sees beside it, with two actions: "Log in" and, while the site takes sign-ups (the self registration setting under Manage authentication), "Create account". The guest account also gets a small "Guest" button that opens what a guest can and cannot do. On a phone only "Log in" stays in the navbar, and the side menu opens with a card offering both. Never shown in the Moodle app or on the login pages. Switched off, the navbar is Boost Union\'s.';
$string['navbarphone_unread'] = '{$a} unread';
$string['navbarstyle'] = 'Navbar style';
$string['navbarstyle_desc'] = 'A dark navbar in the brand colour - Boost Union\'s brand colour setting, a flavour\'s, or Boost\'s default blue - or whatever Boost Union\'s own navbar colour setting and the flavours decide. Choosing \'Boost Union\' hands the navbar back: use it when an organisation\'s flavour sets its own navbar colour and you do not want this theme on top of it.<br />The 3px signature band under the navbar is applied either way; a flavour changes its colour through <code>look_rawscss</code> with <code>--dimensions-navbar-band</code>.';
$string['navbarstyle_inherit'] = 'Leave it to Boost Union';
$string['navbarstyle_navy'] = 'Dark navbar in the brand colour';
$string['pluginname'] = 'Dimensions';
$string['prescssinheritancesetting'] = 'Pre SCSS inheritance';
$string['prescssinheritancesetting_desc'] = 'With this setting, you control if the pre SCSS code from Boost Union should be inherited or duplicated.';
$string['privacy:metadata:cat'] = 'The branding of a course category. Its content is institutional; the only link to a person is the authorship stamp.';
$string['privacy:metadata:cat:timemodified'] = 'When the branding of the category was last saved.';
$string['privacy:metadata:cat:usermodified'] = 'The id of the user who last saved a category branding, kept as an authorship stamp. A data request exports the categories a person last saved, and a deletion request clears the stamp and keeps the branding.';
$string['privacy:metadata:core_cohort'] = 'Each look the setting offers has a cohort, and a person who chooses a look is made a member of its cohort and removed from the others. The membership follows the stored preference and is kept by the cohort subsystem.';
$string['privacy:metadata:preference:category_herofolded'] = 'Whether the person collapsed the header of the category pages.';
$string['privacy:metadata:preference:category_state'] = 'How the person left each of their most recent category pages: the organisation, the view and the filters, by category.';
$string['privacy:metadata:preference:category_view'] = 'Whether the person prefers cards or a list on a category page.';
$string['privacy:metadata:preference:coursenotice_collapsed'] = 'Whether the person folded the course notice of the course pages to its one line.';
$string['privacy:metadata:preference:flavour'] = 'The Boost Union flavour the person chose as their look, or the site default.';
$string['privacy:metadata:preference:focus_expanded'] = 'Whether the person widened the reading column in focus mode.';
$string['privacy:path:branding'] = 'Category branding';
$string['readingbar_status_complete'] = 'Completed';
$string['readingbar_status_pending'] = 'Pending';
$string['recommendation_customfieldpicture_description'] = 'The landing page badges, the share picture and the rest of the landing page are course custom fields that this theme creates in its own category. The badges and the share picture are of the Picture type (customfield_picture), which is recommended but not required: without it, or with it disabled, those five fields are not created and the landing page and the category listing draw without them, while everything else works. Install the plugin and enable the Picture type under Site administration > Plugins > Custom fields > Manage custom field types to offer them. A field deleted by hand is a warning: use the automatic fix to create the missing fields; it is safe to repeat.';
$string['recommendation_customfieldpicture_summary_missing'] = 'These course custom fields of the landing page are missing: {$a}.';
$string['recommendation_customfieldpicture_summary_ok'] = 'The picture field type is enabled and every course field of the landing page exists.';
$string['recommendation_customfieldpicture_summary_type'] = 'The Picture custom field type (customfield_picture) is not installed or not enabled. It is recommended, not required: without it the landing page has no badges and no share picture, and everything else works.';
$string['recommendation_customfieldpicture_title'] = 'Dimensions: Landing page picture fields';
$string['recommendation_landingaddresses_description'] = 'Whether each landing page gets a short public address (/p/…) in its course settings depends on Moodle\'s router being configured, which is an assertion in config.php plus a web server rewrite, not a theme setting. Until it is, every landing page is shared under its long address. Set up the rewrite and $CFG->routerconfigured; Site administration > Server > Environment reports the router.';
$string['recommendation_landingaddresses_summary_off'] = 'Moodle\'s router is not configured on this site, so every landing page is shared under its long address.';
$string['recommendation_landingaddresses_summary_ok'] = 'Moodle\'s router is configured: each landing page gets a short public address (/p/…) in its course settings.';
$string['recommendation_landingaddresses_title'] = 'Dimensions: Landing page addresses';
$string['recommendation_lookcohorts_description'] = 'A look cohort was deleted, through a web service or another plugin, while a smart menu or menu item was restricted by it. Boost Union then removes the cohort from the rule, which would show the menu to everyone, so the theme hid the menu or item first. The cohort comes back with the next run of the reconcile task; restrict each hidden menu or item again and show it, on Boost Union\'s smart menus page.';
$string['recommendation_lookcohorts_summary_hidden'] = 'Smart menus hidden after their look cohort was deleted: {$a->menus}; menu items: {$a->items}.';
$string['recommendation_lookcohorts_summary_ok'] = 'No smart menu or item is hidden because a look cohort was deleted.';
$string['recommendation_lookcohorts_title'] = 'Dimensions: Smart menus restricted by look';
$string['recommendation_profileveto_description'] = 'This theme narrows who may open another person\'s profile: a person may open it when they can see every profile (moodle/user:viewdetails or moodle/user:viewalldetails at the other person\'s user context), when they come from the page of a course in which the other person is a course contact, or when they share a course with the other person in which they may view the participants (moodle/course:viewparticipants). Everyone else is refused, which closes the gap that makes every teacher\'s profile open to every user. The rule only withholds; it never opens a profile core keeps closed. Core consults it only while "Force users to log in for profiles" (forceloginforprofiles) is on: when it is off, core opens every profile to everyone, visitors included, without asking the theme. Turn it on under Site administration > Security > Site security settings.';
$string['recommendation_profileveto_summary_off'] = 'Core\'s login requirement for profiles is off, so every profile is open to everyone and the theme\'s rule is not applied.';
$string['recommendation_profileveto_summary_ok'] = 'Core requires a login for profiles, so the theme\'s profile rule applies.';
$string['recommendation_profileveto_title'] = 'Dimensions: Profile access rule';
$string['recommendation_unlistedcourses_description'] = 'This theme reads the discoverability states of the Course discoverability plugin (local_unlistedcourses) on the category pages, the landing page and the enrolment forwarding, and calls its classes directly. The plugin has no settings, so what is checked is its presence and its upgrade. When it is missing, the anonymous pages answer as if nothing were public, the enrolment ghost check lets everybody through, and the pages that call the plugin directly fail. Install or upgrade it from Site administration > Plugins > Plugins overview.';
$string['recommendation_unlistedcourses_summary_behind'] = 'The Course discoverability plugin is missing or waiting for an upgrade.';
$string['recommendation_unlistedcourses_summary_ok'] = 'The Course discoverability plugin is installed and upgraded.';
$string['recommendation_unlistedcourses_title'] = 'Dimensions: Course discoverability plugin';
$string['selectableflavours'] = 'Looks a person may choose';
$string['selectableflavours_desc'] = 'The Boost Union flavours a logged-in person may choose as their own look. A chosen flavour is shown on every page to the person who chose it, over the flavours the category and cohort rules apply, so each flavour listed here must work outside the category it was made for. Each listed look gets a cohort ("Look: ...") holding the people who chose it, so a smart menu can be restricted by look; do not use those cohorts in a flavour\'s own cohort rule. A look taken off the list keeps its cohort, emptied. With none ticked, nobody can choose and Boost Union\'s rules decide the look as before.';
$string['settingsoverviewdesc'] = 'With Dimensions, you extend Boost Union with its own login page, category showcase, landing pages and focus mode.';
$string['task_empty_look_cohort'] = 'Empty the cohort of a look no longer offered';
$string['task_materialise_focusmode_default'] = 'Write the previous focus mode default into existing courses';
$string['task_reconcile_look_cohorts'] = 'Keep the look cohorts in step with the chosen looks';
$string['task_warm_flavour_css'] = 'Compile the flavour stylesheets no visitor has asked for yet';
$string['unavailableheading'] = 'This content is not available';
$string['unavailablemessage'] = 'This page is not available for your profile. If you believe you should have access, please contact the course administration.';
$string['unavailabletitle'] = 'Content not available';
